mapper.select:
SELECT * FROM plan_day_route_maps
WHERE plan_id = #{planId} AND day_number = #{dayNumber} AND style = #{style}
LIMIT 1

SELECT * FROM plan_day_route_maps
WHERE plan_id = #{planId}

    AND style = #{style}

ORDER BY day_number ASC, style ASC

SELECT * FROM plan_day_route_maps WHERE status IN
#{status}
ORDER BY updated_at ASC, id ASC

SELECT * FROM plan_day_route_maps
WHERE status = 'failed'
  AND error_code = 'ROUTE_MAP_DISPATCH_FAILED'
  AND updated_at <= #{cutoff}
ORDER BY updated_at ASC, id ASC
LIMIT #{limit}

SELECT COUNT(*)
FROM plan_day_route_maps
WHERE user_id = #{userId}
  AND created_at >= #{start}
  AND created_at < #{end}

SELECT status AS status, COUNT(*) AS count
FROM plan_day_route_maps
WHERE created_at >= #{start}
  AND created_at < #{end}
GROUP BY status
ORDER BY count DESC, status ASC

SELECT error_code AS errorCode, COUNT(*) AS count
FROM plan_day_route_maps
WHERE created_at >= #{start}
  AND created_at < #{end}
  AND status IN ('failed', 'fallback')
  AND error_code IS NOT NULL
GROUP BY error_code
ORDER BY count DESC, error_code ASC
LIMIT #{limit}
